package com.labmaker.app;
import org.json.*;import okhttp3.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
final class APIModels {
 static final class Failure extends IOException {Failure(String message){super(message);}}
 static String keyFor(String base,String draft,JSONObject stored)throws Exception {String secret=draft==null?"":draft.trim();if(secret.isEmpty()){if(stored==null||!base.equals(stored.optString("endpoint")))throw new Failure("当前地址未配置密钥，请填写密钥后获取模型");secret=stored.optString("key");}if(secret.isEmpty()||secret.length()>4096||secret.chars().anyMatch(c->c<33||c>126))throw new Failure("密钥格式无效");return secret;}
 static JSONObject draft(String base,String model,String key,JSONObject stored)throws Exception {String name=model==null?"":model.trim();if(name.isEmpty()||name.length()>256||name.chars().anyMatch(c->c<32||c==127))throw new Failure("模型名称无效");return new JSONObject().put("endpoint",base).put("model",name).put("key",keyFor(base,key,stored));}
 static JSONObject parse(byte[] bytes,String secret)throws Exception {JSONObject root=new JSONObject(new String(bytes,StandardCharsets.UTF_8));JSONArray data=root.optJSONArray("data");if(data==null)throw new Failure("服务未返回兼容的模型列表，请手动填写模型名称");if(data.length()>10000)throw new Failure("模型列表过大，请手动填写模型名称");SortedSet<String> names=new TreeSet<>();for(int i=0;i<data.length();i++){JSONObject item=data.optJSONObject(i);if(item==null||!(item.opt("id") instanceof String))continue;String id=item.getString("id").trim();if(!id.isEmpty()&&id.length()<=256&&id.chars().noneMatch(c->c<32||c==127)&&(secret.isEmpty()||!id.contains(secret)))names.add(id);}if(names.isEmpty())throw new Failure("模型列表为空或没有可用标识，请手动填写模型名称");return new JSONObject().put("models",new JSONArray(names)).put("partial",root.optBoolean("has_more",false));}
 static JSONObject read(Call request,String secret)throws Exception {try(Response response=request.execute()){int code=response.code();if(!response.isSuccessful()){String reason=code==401||code==403?"鉴权失败，请检查密钥及访问权限":code==404||code==405?"该服务不支持模型列表，请手动填写模型名称":code==429?"服务限流，请稍后重试":code>=300&&code<400?"服务返回重定向，请填写最终 API 地址":"模型列表服务暂不可用";throw new Failure(reason+"（HTTP "+code+"）");}if(response.body()==null)throw new Failure("模型列表响应为空");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[8192];int count;try(InputStream in=response.body().byteStream()){while((count=in.read(block))!=-1){if(out.size()+count>1024*1024)throw new Failure("模型列表超过 1 MB，请手动填写模型名称");out.write(block,0,count);}}try{return parse(out.toByteArray(),secret);}catch(IOException e){throw e;}catch(Exception e){throw new Failure("模型列表格式不兼容，请手动填写模型名称");}}}
}
